import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        // [0]=合格 [1]=失敗 [2]=未実施
        Map<String, int[]> byPhase = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            int[] counts = byPhase.computeIfAbsent(parts[1], key -> new int[3]);
            switch (parts[2]) {
                case "合格" -> counts[0]++;
                case "失敗" -> counts[1]++;
                default -> counts[2]++;
            }
        }

        int doneTotal = 0;
        int all = 0;
        int pending = 0;
        for (Map.Entry<String, int[]> entry : byPhase.entrySet()) {
            int[] c = entry.getValue();
            int done = c[0] + c[1];
            int total = done + c[2];
            doneTotal += done;
            all += total;
            pending += c[2];
            System.out.println(entry.getKey() + " " + done + "/" + total
                    + " 合格 " + c[0] + " 失敗 " + c[1]);
        }
        System.out.printf("消化率 %.1f%n", doneTotal * 100.0 / all);
        System.out.println("未実施 " + pending);
    }
}

