        String[] parts = sc.nextLine().trim().split("\\s+");
        for (int i = 0; i < n; i++) {
            found[i] = Integer.parseInt(parts[i]);
        }
        int total = 0;
        for (int value : found) {
            total += value;
        }
        int recent = 0;
        for (int i = Math.max(0, n - 3); i < n; i++) {
            recent += found[i];
        }

        System.out.println("累計 " + total);
        System.out.printf("平均 %.1f%n", total / (double) n);
        System.out.println("直近3日 " + recent);
        System.out.println("判定 " + (recent <= total * 0.10 ? "収束" : "未収束"));
    }
}

