import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, String[]> needs = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            needs.put(parts[0], parts[1].split(","));
        }
        int m = Integer.parseInt(sc.nextLine().trim());
        Set<String> covered = new HashSet<>();
        for (int i = 0; i < m; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            covered.add(parts[1] + ">" + parts[2]);
        }

        int complete = 0;
        for (Map.Entry<String, String[]> entry : needs.entrySet()) {
            List<String> missing = new ArrayList<>();
            for (String phase : entry.getValue()) {
                if (!covered.contains(entry.getKey() + ">" + phase)) {
                    missing.add(phase);
                }
            }
            if (missing.isEmpty()) {
                complete++;
            } else {
                System.out.println(entry.getKey() + " 未確認 " + String.join(",", missing));
            }
        }
        System.out.println("確認済み " + complete + "/" + n);
    }
}

